export function o11DataChannel({runAnvil,call,work}) {
  let sequence=0;
  const identifiers=new Map();let cachedSchema;
  const args=()=>['data','--studio',...(call.host?['--host',call.host]:[]),'--module',call.module,'--oml',path.resolve(call.oml),'--work',work];
  const run=async(request,flags=[])=>{
    const argv=args();if(request!==undefined) {const dir=path.join(work,'requests');fs.mkdirSync(dir,{recursive:true});const file=path.join(dir,`load-${process.pid}-${++sequence}-${hash(request).slice(0,12)}.json`);atomic(file,request);argv.splice(argv.length-2,0,'--request',file);}
    argv.push(...flags);const raw=await runAnvil(argv);
    if(raw?.unknown || (raw?.timedOut&&!raw?.envelope)) {const error=new Error(channelErrorText(raw.error??'O11 transport lost the response; resume the same batch UUID'));error.code=raw.code??'DATA_OUTCOME_UNKNOWN';error.outcome='uncertain';error.replayable=true;throw error;}
    const reply=unwrap(raw);
    if(raw?.envelope?.ok===false && reply!==raw.envelope && reply?.ok!==false)return{...reply,ok:false,code:reply?.code??raw.envelope.code,error:reply?.error??raw.envelope.error};
    return reply;
  };
  const schema=async()=>{if(cachedSchema)return cachedSchema;const reply=await run(undefined,['--schema']);if(reply?.ok===false)channelThrow(reply,'Kernel schema read failed');for(const entity of reply?.entities??[])if(idOf(entity))identifiers.set(entity.name,idOf(entity));cachedSchema=reply;return reply;};
  return {
    identity:async()=>{const resolved=await schema(),entity=resolved?.entities?.find(e=>e.name===call.entity);if(!resolved?.moduleKey||!entity?.key||!call.host)throw new Error('Canonical module/entity keys and explicit host are required; compile the updated kernel');return{lane:'o11',host:call.host,moduleKey:resolved.moduleKey,entityKey:entity.key,module:resolved.module??call.module,entity:entity.name};},
    schema,
    check:async(request,{dryRun=false}={})=>{const reply=await run(request?.authorization!==undefined?{...request,authorization:hashedWords(request.authorization)}:request,['--check',...(dryRun?['--no-write-fields']:[])]);if(reply?.ok===false&&(!Array.isArray(reply.problems)||!reply.problems.length))channelThrow(reply,'Kernel check failed');return reply;},
    readAll:async(entity,{fields,offset,limit,deadlineAt})=>{const reply=await run({batch:[{operation:'read-all',entity,offset,limit,deadlineMs:Math.max(1000,Math.min(120000,deadlineAt-Date.now()))}]});const result=reply?.results?.[0]??reply;if(result?.ok===false||reply?.ok===false)channelThrow(result?.error?result:reply,'Kernel data read failed');return result?.records?{...result,records:result.records.map(row=>Object.fromEntries(Object.entries(row).filter(([name])=>fields.includes(name))))}:result;},
    write:async(ops)=>{
      const wire=ops.map(op=>Object.fromEntries(['operation','entity','operationId','records','authorization','tenantId','step'].filter(name=>op[name]!==undefined).map(name=>[name,name==='authorization'?hashedWords(op[name]):op[name]])));
      let reply;
      try {reply=await run({...(wire[0]?.authorization!==undefined?{authorization:wire[0].authorization}:{}),batch:wire});}
      catch(error) {return ops.map(()=>({...channelWriteResult(error,channelNoSubmission(error)?'not-submitted':'uncertain',[],[],error.message),replayable:!channelNoSubmission(error)&&(error.replayable??!/Uncertain write/i.test(error.message))}));}
      const results=reply?.results??[reply];
      return ops.map((op,index)=>results[index]?channelAcknowledge(results[index],{...op,identifier:op.identifier??identifiers.get(op.entity)}, {base:0,ordered:true}):channelWriteResult(reply,'not-submitted',[],[],'The kernel stopped before this operation'));
    }
  };
}

export function odcDataChannel({studioData,module,entity,pid,authorize}) {
  const read=async(name,options)=>{const reply=unwrap(await studioData({op:'read',module,entity:name,pid,...options}));if(reply?.ok===false)channelThrow(reply,'Studio data read failed');return reply;};
  const identifiers=new Map(),schemaPages=new Map();
  let contextPage;
  const context=async()=>{const page=contextPage??await read(entity,{limit:1});contextPage=page;schemaPages.set(entity,page);if(typeof page?.tenant!=='string'||!page.tenant.trim())throw new Error('The connected Studio did not identify its tenant');const rows=pageRows(page),identifier=page.identifier??(rows[0]?Object.keys(rows[0])[0]:undefined);if(identifier)identifiers.set(entity,identifier);return{tenant:page.tenant,moduleKey:page.moduleKey,entityKey:page.entityKey,identifier};};
  const text=value=>value==null||value===''?null:typeof value==='string'?value:typeof value==='boolean'?(value?'True':'False'):JSON.stringify(value);
  const nativeRecords=op=>op.records.map((record,index)=>{
    const identifier=op.identifier??identifiers.get(op.entity??entity),id=identifier?text(record[identifier]):null;
    return{id:id||`new-${index+1}`,attributes:Object.entries(record).filter(([name])=>!identifier||name.toLowerCase()!==identifier.toLowerCase()).map(([name,value])=>({name,value:text(value)}))};
  });
  const evidenceFor=(reply,op)=>{
    const match=/the full report is in\s+(.+?)(?:\. Do not repeat|\r?\n|$)/i.exec(String(reply?.error??reply?.message??''));
    if(!match)return null;
    const file=match[1].trim().replace(/^['"]|['"]$/g,'');
    if(!path.isAbsolute(file)||/^(?:https?:|agent:|file:|\\\\|\/\/)/i.test(file))return{invalid:true,error:'The native evidence is remote or is not an absolute local file'};
    {const hosted=hostedContext();if(hosted&&!insideVisible(path.resolve(hosted.workspace),file))return{invalid:true,error:'The native evidence is a file of the user\'s machine, which this server does not read'};}
    try {
      const evidence=JSON.parse(fs.readFileSync(file,'utf8').replace(/^\uFEFF/,''));
      if(evidence.count!==op.records.length||JSON.stringify(evidence.request?.records)!==JSON.stringify(nativeRecords(op)))return{invalid:true,error:'The native evidence does not match the submitted batch'};
      return{evidence,file};
    } catch {return{invalid:true,error:'The native evidence cannot be read locally'};}
  };
  const acknowledge=(reply,op,transportError=false)=>{
    const evidence=evidenceFor(reply,op);
    if(evidence?.invalid)return channelWriteResult({...reply,error:`${evidence.error}; ${channelFailure(reply,'Native write failed').error}`,code:'DATA_OUTCOME_UNKNOWN'},'uncertain');
    if(evidence) {
      // StartupHook maps InvalidOperationException to gate_refused even after native rows
      // were written. A correlated DataCommands report is authoritative over that wrapper.
      const {outcome,gate,submitted,sent,...native}=evidence.evidence;
      return channelAcknowledge({...native,error:reply?.error??native.error,code:reply?.code??native.code,evidenceFile:evidence.file},op,{base:1});
    }
    if(Array.isArray(reply?.reports)&&reply.reports.length)return channelAcknowledge(reply,op,{base:1});
    if(reply?.outcome==='uncertain'||reply?.outcome==='native_error'||/Uncertain write/i.test(String(reply?.error??'')))return channelWriteResult(reply,'uncertain',[],[],'The Studio write outcome is unknown');
    // Partial row diagnostics prove submission even if WithoutStack cut the evidence path.
    if(/\b\d+\s+of\s+\d+\s+records?\s+failed\b/i.test(String(reply?.error??reply?.message??'')))return channelWriteResult(reply,'uncertain',[],[],'Native rows failed without a readable correlated report');
    const provenNotSent=reply?.sent===false || reply?.submitted===0 || reply?.outcome==='gate_refused' || /ODC Studio is not running/i.test(String(reply?.error??''));
    if(provenNotSent)return channelWriteResult(reply,'not-submitted',[],[],'The native command was not submitted');
    return channelWriteResult(reply,'uncertain',[],[],transportError?'The Studio transport lost the write response':'The native write has no complete acknowledgment or proof that nothing was sent');
  };
  return {
    context,
    identity:async()=>{const target=await context();if(!target.moduleKey||!target.entityKey||!target.identifier)throw new Error('The Studio did not resolve the producer moduleKey/entityKey and identifier; no data write is safe');return{lane:'odc',host:target.tenant,tenant:target.tenant,moduleKey:target.moduleKey,entityKey:target.entityKey,module,entity};},
    schema:async(names)=>({entities:await Promise.all(names.map(async name=>{const page=schemaPages.get(name)??await read(name,{limit:1});schemaPages.delete(name);const rows=pageRows(page);const attrs=Array.isArray(page.attributes)?page.attributes.map(a=>typeof a==='string'?{name:a.slice(0,a.indexOf(':')),type:a.slice(a.indexOf(':')+1)}:a):Object.entries(page.attributes??{}).map(([name,type])=>({name,type}));const identifier=page.identifier??(rows[0]?Object.keys(rows[0])[0]:undefined);identifiers.set(name,identifier);return{name,key:page.entityKey,moduleKey:page.moduleKey,identifier,...(typeof page.identifierAutoNumber==='boolean'?{identifierAutoNumber:page.identifierAutoNumber}:{}),indexes:page.indexes??[],attributes:attrs};}))}),
    readAll:(name,options)=>read(name,options),
    write:async(ops)=>{
      const results=[];
      for(const op of ops) {
        let reply,transportError=false;
        try {reply=unwrap(await studioData({op:op.operation,module,entity:op.entity??entity,records:op.records,pid,authorize:op.authorization??authorize,name:`${op.operationId}-${op.batch}.json`}));}
        catch(error) {reply={...error,error:error.message};transportError=true;}
        const result=acknowledge(reply,{...op,identifier:op.identifier??identifiers.get(op.entity??entity)},transportError);
        results.push(result);if(result.outcome!=='completed')break;
      }
      while(results.length<ops.length)results.push(channelWriteResult(results.at(-1),'not-submitted',[],[],'The Studio stopped before this operation'));
      return results;
    }
  };
}
